// alwaysOutputData yields one empty item for an empty table, so rows
// without their key column are skipped.
const sub = $("GET /workations").first().json.jwtPayload.sub;
const trips = $("Get workations").all().map((i) => i.json).filter((r) => r.workation_id);
const signups = $("Get signups").all().map((i) => i.json).filter((r) => r.workation_id);
const profiles = $("Get profiles").all().map((i) => i.json).filter((r) => r.user_sub);

const nameBySub = new Map(profiles.map((p) => [p.user_sub, p.name ?? ""]));
const profileBySub = new Map(profiles.map((p) => [p.user_sub, p]));
// The Slack thread of the pitch each trip started as: "Pitch decisions"
// sets a confirmed pitch's workation_id. A trip made by hand has none.
const threadByTrip = new Map(
  $("Get pitches")
    .all()
    .map((i) => i.json)
    .filter((p) => p.workation_id && p.slack_url)
    .map((p) => [p.workation_id, p.slack_url]),
);
const orEmpty = (value) => (typeof value === "string" && value.trim() ? value.trim() : null);
// Who has a spot ("going") or is waiting ("waitlist"), oldest row first, so
// the waitlist is in line order. One entry per person. Every colleague gets
// these lists: display fields only, and the caller flagged with isMe,
// never anyone's sub or email.
const people = (workationId, status) => {
  const seen = new Set();
  return signups
    .filter((s) => s.workation_id === workationId && s.status === status)
    .sort((a, b) => String(a.createdAt).localeCompare(String(b.createdAt)))
    .filter((s) => !seen.has(s.user_sub) && seen.add(s.user_sub))
    .map((s) => {
      const profile = profileBySub.get(s.user_sub) ?? {};
      return {
        name: profile.name ?? "",
        team: orEmpty(profile.team),
        jobTitle: orEmpty(profile.jobTitle),
        isMe: s.user_sub === sub,
      };
    });
};

return [
  {
    json: {
      workations: trips.map((row) => {
        const organizerName = nameBySub.get(row.organizer);
        const going = people(row.workation_id, "going");
        const waitlist = people(row.workation_id, "waitlist");
        return {
          workationId: row.workation_id,
          slug: row.slug,
          title: row.title,
          place: row.place,
          // String columns, YYYY-MM-DD: sent exactly as stored.
          startDate: row.start_date ?? "",
          endDate: row.end_date ?? "",
          description: row.description ?? "",
          imageUrl: row.image_url ?? "",
          imageAlt: row.image_alt ?? "",
          // Carried over from the pitch by "Pitch decisions", or entered by hand.
          accommodationUrl: row.accommodation_url ?? "",
          costEstimate: typeof row.cost_estimate === "number" ? row.cost_estimate : null,
          costIncludes: row.cost_includes ?? "",
          // The pitch's discussion thread, or "" (see threadByTrip).
          slackUrl: threadByTrip.get(row.workation_id) ?? "",
          // The trip's Drive folder, once "Trip Drive Folders" has opened it
          // to everyone at n8n.io (the morning after the trip ends), else "".
          photosUrl: row.drive_domain_shared === true ? (row.drive_folder_url ?? "") : "",
          attendees: going.length,
          capacity: typeof row.capacity === "number" ? row.capacity : null,
          waitlisted: waitlist.length,
          going,
          waitlist,
          // Every colleague gets this list: display fields only,
          // never the organizer's sub or email.
          organizer: organizerName ? { name: organizerName } : null,
        };
      }),
    },
  },
];
